<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import {onShow,onHide,onResize,onShareAppMessage} from '@dcloudio/uni-app';
import {deviceDataLabel,getPlatformLayout,isWeixinMiniProgram} from '../../services/platform';
import UniIcons from '@club-ui/uni-icons/uni-icons.vue';
import UniNumberBox from '@club-ui/uni-number-box/uni-number-box.vue';
import { api, useIdentity } from '../../store';
import {orderIncome} from '../../services/order-income';
import {serviceAvailability} from '../../services/service-availability';
import {emptyHallFilterDraft,parseHallFilter,matchesHallFilter,type HallFilterDraft} from '../../services/hall-filter';
import {emptyHallPreferences,loadHallPreferences,saveHallPreferences} from '../../services/hall-preferences';
import {createUniStorage} from '../../services/storage';
import { ApiError, DEFAULT_ESCORT_TASK, canServe, qualifiedGames, money, compactMoney, statusLabels, serviceLabels, time, orderMembers, participantEarnings, orderSummary, type Game, type Player, type Order, type Settlement, type ClubSettings, type ServiceType, type Application, type Product } from '@stellar/core';
const identity=useIdentity();
const platformLayout=ref(getPlatformLayout());
const appStyle=computed(()=>platformLayout.value?{'--club-safe-bottom':platformLayout.value.safeBottom+'px'}:{});
const topbarStyle=computed(()=>platformLayout.value?{height:platformLayout.value.navHeight+'px',paddingTop:platformLayout.value.topPadding+'px',paddingRight:platformLayout.value.rightPadding+'px',paddingBottom:'8px'}:{});
const sheetStyle=computed(()=>platformLayout.value?{height:platformLayout.value.sheetHeight+'px'}:{});
const tab=ref('home'),selectedGame=ref('all'),serviceType=ref<ServiceType>('hourly'),search=ref(''),statusFilter=ref('all'),orderScope=ref('all');
const games=ref<Game[]>([]),players=ref<Player[]>([]),orders=ref<Order[]>([]),hall=ref<Order[]>([]),settlements=ref<Settlement[]>([]),settings=ref<ClubSettings|null>(null),applications=ref<Application[]>([]);
const products=ref<Product[]>([]),myProducts=ref<Product[]>([]),selectedProduct=ref<Product|null>(null);
const productType=ref<ServiceType>('hourly'),productGame=ref('delta'),productTitle=ref(''),productDescription=ref(''),productPrice=ref('68'),productTask=ref(DEFAULT_ESCORT_TASK);
// Keep uni calls explicit so the H5 compiler includes its storage APIs.
const hallFilterStorage=createUniStorage({getStorageSync:key=>uni.getStorageSync(key),setStorageSync:(key,value)=>uni.setStorageSync(key,value)});
const hallPreferences=ref(emptyHallPreferences());
watch(()=>identity.session?.userId,userId=>{hallPreferences.value=loadHallPreferences(hallFilterStorage,userId||'guest');},{immediate:true});
const hallFilterEnabled=computed(()=>hallPreferences.value[serviceType.value].enabled);
const hallFilterDraft=ref<HallFilterDraft>(emptyHallFilterDraft());
const activeHallFilter=computed(()=>parseHallFilter(serviceType.value,hallPreferences.value[serviceType.value].conditions));
const hallFilterCount=computed(()=>Number(activeHallFilter.value.minHours!==undefined||activeHallFilter.value.maxHours!==undefined)+Number(activeHallFilter.value.minEarnings!==undefined||activeHallFilter.value.maxEarnings!==undefined));
const hallFilteringActive=computed(()=>hallFilterEnabled.value&&hallFilterCount.value>0);
const hallFilterSummary=computed(()=>{const f=activeHallFilter.value;const range=(min:number|undefined,max:number|undefined,unit:string)=>min===undefined?(max===undefined?'':`${max}${unit}及以下`):max===undefined?`${min}${unit}及以上`:`${min}～${max}${unit}`;return [range(f.minHours,f.maxHours,'小时'),range(f.minEarnings===undefined?undefined:f.minEarnings/100,f.maxEarnings===undefined?undefined:f.maxEarnings/100,'元')].filter(Boolean).join(' · ');});
const loading=ref(true),refreshing=ref(false),busy=ref(false),error=ref('');
type Sheet='accounts'|'player'|'checkout'|'pay'|'order'|'refund'|'finish'|'help'|'apply'|'assistants'|'publish-menu'|'publish-product'|'product'|'my-products'|'hall-filter';
const sheet=ref<Sheet|null>(null),selectedPlayer=ref<Player|null>(null),selectedOrder=ref<Order|null>(null);
const checkoutGame=ref('valorant'),checkoutType=ref<ServiceType>('hourly'),region=ref(''),quantity=ref(1),note=ref(''),task=ref(DEFAULT_ESCORT_TASK),taskPrice=ref('128'),agreed=ref(true);
const refundReason=ref(''),refundAmount=ref(0),finishNote=ref(''),taskConfirmed=ref(false),applyType=ref<ServiceType>('hourly'),applyGames=ref<string[]>([]),introduction=ref('');
const now=ref(Date.now()),toast=ref('');let toastTimer:ReturnType<typeof setTimeout>;let interval:ReturnType<typeof setInterval>;let ticker:ReturnType<typeof setInterval>;
const me=computed(()=>players.value.find(p=>p.userId===identity.session?.userId));
const isMine=(o:Order)=>o.bossId===identity.session?.userId;
const isLead=(o:Order)=>o.playerId===me.value?.id;
const isInvited=(o:Order)=>o.status==='waiting'&&o.preferredPlayerId===me.value?.id;
const isMember=(o:Order)=>orderMembers(o).some(m=>m.playerId===me.value?.id);
const qualified=(type:ServiceType)=>!!me.value?.approved&&!!me.value.qualifications.includes(type);
const publishableTypes=computed(()=>(['hourly','escort'] as ServiceType[]).filter(type=>!!me.value&&games.value.some(g=>canServe(me.value!,type,g.id))));
const canReceiveOrders=computed(()=>publishableTypes.value.length>0);
const orderScopes=[{id:'all',label:'全部订单'},{id:'created',label:'我下单的'},{id:'joined',label:'我参与的'},{id:'invited',label:'邀请我的'}];
const visibleOrderScopes=computed(()=>canReceiveOrders.value?orderScopes:orderScopes.slice(0,1));
watch(canReceiveOrders,allowed=>{if(!allowed){orderScope.value='all';if(tab.value==='hall')navigate('home');if(['publish-menu','publish-product','hall-filter'].includes(sheet.value||''))sheet.value=null;}});
const demoAccounts=[{id:'u-boss',name:'林序'},{id:'u-hourly',name:'小屿'},{id:'u-escort',name:'凛'},{id:'u-player',name:'岚'}];
function accountStatus(userId:string){const p=players.value.find(p=>p.userId===userId);const types=p?.approved?p.qualifications:[];return types.includes('hourly')?(types.includes('escort')?'组队与护航资格均已开通':'仅组队资格 · 护航未开通'):(types.includes('escort')?'仅护航资格 · 组队未开通':'无商品发布或接单资格');}

const displayProducts=computed(()=>products.value.filter(p=>(p.serviceType===serviceType.value)&&(selectedGame.value==='all'||p.gameId===selectedGame.value)&&[p.title,p.sellerName,gameName(p.gameId),p.description].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const productSeller=(p:Product)=>players.value.find(v=>v.id===p.playerId);
const checkoutPlayers=computed(()=>players.value.filter(p=>p.userId!==identity.session?.userId&&canServe(p,checkoutType.value,checkoutGame.value)));
const ownPublished=computed(()=>myProducts.value.filter(p=>p.active).length);
const displayHall=computed(()=>hall.value.filter(o=>o.serviceType===serviceType.value&&(selectedGame.value==='all'||o.gameId===selectedGame.value)&&matchesHallFilter(o,activeHallFilter.value,hallFilterEnabled.value)));
const displayOrders=computed(()=>orders.value.filter(o=>(orderScope.value==='all'||(orderScope.value==='created'?isMine(o):orderScope.value==='invited'?isInvited(o):isMember(o)))&&(statusFilter.value==='all'||(statusFilter.value==='refund'?o.refundStatus==='pending':statusFilter.value==='active'?['waiting','accepted','serving','confirming'].includes(o.status):o.status===statusFilter.value))));
const orderIncomeById=computed(()=>Object.fromEntries(orders.value.map(o=>[o.id,orderIncome(o,me.value?.id,settlements.value)])));
const selectedIncome=computed(()=>selectedOrder.value?orderIncome(selectedOrder.value,me.value?.id,settlements.value):null);
const currentGame=computed(()=>games.value.find(g=>g.id===checkoutGame.value));
const checkoutPrice=computed(()=>selectedProduct.value?.price??(checkoutType.value==='escort'?Math.round(Number(taskPrice.value)*100):selectedPlayer.value?.price??Math.min(...players.value.filter(p=>p.approved&&p.qualifications.includes('hourly')&&canServe(p,'hourly',checkoutGame.value)).map(p=>p.price),6800)));
const checkoutTotal=computed(()=>checkoutPrice.value*(checkoutType.value==='escort'?1:quantity.value));
const assistantCandidates=computed(()=>players.value.filter(p=>p.approved&&p.available&&!p.busy&&canServe(p,'escort',selectedOrder.value?.gameId||'')&&p.userId!==selectedOrder.value?.bossId&&!orderMembers(selectedOrder.value!).some(m=>m.playerId===p.id)));
const gameName=(id:string)=>games.value.find(g=>g.id===id)?.name||id;
const gameColor=(id:string)=>games.value.find(g=>g.id===id)?.color||'#b0a2fc';
const activeCount=computed(()=>orders.value.filter(o=>['waiting','accepted','serving','confirming'].includes(o.status)).length);
const applicationFor=(type:ServiceType)=>applications.value.find(a=>a.serviceType===type);
const applicationLabel=(a?:Application)=>a?({pending:'资料审核中',assessment:'考核进行中',approved:'考核通过',rejected:'未通过 · 可重新申请'}[a.status]):'尚未申请';
const remaining=(o:Order)=>Math.max(0,o.quantity*3600000-(now.value-(o.startedAt??now.value))-(o.demoElapsedMs||0));
const countdown=(o:Order)=>{const m=Math.ceil(remaining(o)/60000);return m>0?`剩余 ${Math.floor(m/60)} 小时 ${m%60} 分钟`:'约定时长已完成';};
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200);}
async function run(job:()=>Promise<void>){if(busy.value)return;busy.value=true;try{await job();}catch(e){notify(e instanceof Error?e.message:'操作失败，请重试');}finally{busy.value=false;}}
async function load(silent=false){if(refreshing.value)return;refreshing.value=true;if(!silent)loading.value=true;try{if(!identity.session)await identity.login('user');const [g,p,o,s,h,w,a,goods,owned]=await Promise.all([api.games(),api.players(),api.orders(),api.settings(),api.orders({scope:'hall'}),api.wallet(),api.applications(),api.products(),api.products('mine')]);games.value=g;players.value=p;if(selectedPlayer.value)selectedPlayer.value=p.find(v=>v.id===selectedPlayer.value?.id)||selectedPlayer.value;orders.value=o;settings.value=s;hall.value=h;settlements.value=w.settlements;applications.value=a;products.value=goods;myProducts.value=owned;if(selectedOrder.value)selectedOrder.value=o.find(v=>v.id===selectedOrder.value?.id)||h.find(v=>v.id===selectedOrder.value?.id)||selectedOrder.value;error.value='';}catch(e){if(e instanceof ApiError&&e.code===401){await identity.login('user');refreshing.value=false;await load(silent);return;}error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;refreshing.value=false;}}
async function switchAccount(userId:string){await run(async()=>{await identity.login('user',userId);selectedOrder.value=null;sheet.value=null;orderScope.value='all';statusFilter.value='all';await load();notify('已切换体验账号，发布商品与接单按资格开放');});}
function openPlayer(p:Player){selectedPlayer.value=p;sheet.value='player';}
function publishGames(type:ServiceType,p?:Player|null){return me.value?qualifiedGames(me.value,type).filter(id=>!p||qualifiedGames(p,type).includes(id)):[];}
function book(p?:Player,product?:Product){
  if((p&&p.userId===identity.session?.userId)||(product&&product.userId===identity.session?.userId)){notify('不能给自己下单');return;}
  selectedProduct.value=product||null;selectedPlayer.value=p||null;checkoutType.value=product?.serviceType||serviceType.value;
  const available=p?qualifiedGames(p,checkoutType.value):games.value.map(g=>g.id);const initial=product?.gameId||(selectedGame.value!=='all'&&available.includes(selectedGame.value)?selectedGame.value:available[0]);
  selectGame(initial||games.value[0]?.id||'delta');quantity.value=1;note.value='';task.value=product?.task||DEFAULT_ESCORT_TASK;taskPrice.value=String((product?.price||12800)/100);agreed.value=true;sheet.value='checkout';
}
function chooseCheckoutType(type:ServiceType){if(selectedProduct.value)return;checkoutType.value=type;selectedPlayer.value=null;selectGame(checkoutGame.value);}
function selectGame(id:string){checkoutGame.value=id;region.value=games.value.find(g=>g.id===id)?.regions[0]||'';if(selectedPlayer.value&&!canServe(selectedPlayer.value,checkoutType.value,id))selectedPlayer.value=null;}
function chooseProvider(p?:Player){if(selectedProduct.value)return;selectedPlayer.value=p||null;}
async function createOrder(){await run(async()=>{if((selectedPlayer.value&&selectedPlayer.value.userId===identity.session?.userId)||(selectedProduct.value&&selectedProduct.value.userId===identity.session?.userId)){notify('不能给自己下单');return;}if(checkoutType.value==='escort'&&!task.value.trim()){notify('请填写护航任务项');return;}if(!agreed.value){notify('请先确认服务说明');return;}selectedOrder.value=await api.createOrder({productId:selectedProduct.value?.id,serviceType:checkoutType.value,task:task.value,taskPrice:Math.round(Number(taskPrice.value)*100),gameId:checkoutGame.value,region:region.value,quantity:checkoutType.value==='escort'?1:quantity.value,playerId:selectedPlayer.value?.id,note:note.value});await load(true);sheet.value='pay';});}
function payOrder(o:Order){selectedOrder.value=o;sheet.value='pay';}
function openProduct(p:Product){selectedProduct.value=p;sheet.value='product';}
function openPublish(type:ServiceType){if(!publishableTypes.value.includes(type)){sheet.value=null;notify('该类型商品发布资格尚未开通');return;}productType.value=type;productGame.value=publishGames(type)[0]||'delta';productTitle.value='';productDescription.value='';productPrice.value=type==='escort'?'128':String((me.value?.price||6800)/100);productTask.value=DEFAULT_ESCORT_TASK;sheet.value='publish-product';}
async function publishProduct(){await run(async()=>{await api.publishProduct({serviceType:productType.value,gameId:productGame.value,title:productTitle.value,description:productDescription.value,price:Math.round(Number(productPrice.value)*100),task:productTask.value});await load(true);sheet.value='my-products';notify('商品发布成功，可在发现页查看');});}
async function toggleProduct(p:Product){await run(async()=>{await api.updateProduct(p.id,!p.active);await load(true);notify(p.active?'商品已下架':'商品已上架');});}
function persistHallPreferences(){if(!saveHallPreferences(hallFilterStorage,identity.session?.userId||'guest',hallPreferences.value))notify('当前设备无法保存筛选条件，本次设置仍会生效');}
function toggleHallFilter(){hallPreferences.value[serviceType.value].enabled=!hallFilterEnabled.value;persistHallPreferences();}
function openHallFilter(){hallFilterDraft.value={...hallPreferences.value[serviceType.value].conditions};sheet.value='hall-filter';}
function applyHallFilter(){try{parseHallFilter(serviceType.value,hallFilterDraft.value);hallPreferences.value[serviceType.value].conditions={...hallFilterDraft.value};sheet.value=null;persistHallPreferences();}catch(e){notify(e instanceof Error?e.message:'筛选条件无效');}}
function clearHallFilter(){hallPreferences.value[serviceType.value].conditions=emptyHallFilterDraft();persistHallPreferences();}
function openOrder(o:Order){selectedOrder.value=o;sheet.value='order';}
async function action(name:string,o=selectedOrder.value,body?:unknown){if(!o)return;if(name==='accept'&&!me.value?.available){notify('请先在“我的”开启接单状态');return;}await run(async()=>{selectedOrder.value=await api.act(o.id,name,body);await load(true);sheet.value='order';if(name==='pay'||name==='accept')tab.value='orders';notify(({pay:'模拟支付成功，等待接单',accept:'接单成功',start:'服务已开始，协作名单已锁定',finish:'已提交，等待下单用户确认',confirm:'订单已完成',refund:'退款申请已提交','add-assistant':'副手已加入，净报酬按人数均分','demo-elapse':'已模拟完成约定时长'} as Record<string,string>)[name]||'操作成功');});}
function refund(o:Order){selectedOrder.value=o;refundReason.value='';refundAmount.value=o.amount/100;sheet.value='refund';}
function finish(o:Order){selectedOrder.value=o;finishNote.value='';taskConfirmed.value=false;sheet.value='finish';}
function openApply(type:ServiceType){const current=applicationFor(type);if(['pending','assessment'].includes(current?.status||'')){sheet.value=null;tab.value='me';notify('该类型正在审核或考核中，可在此查看进度');return;}applyType.value=type;applyGames.value=[];introduction.value='';sheet.value='apply';}
function toggleGame(id:string){applyGames.value=applyGames.value.includes(id)?applyGames.value.filter(g=>g!==id):[...applyGames.value,id];}
async function submitApplication(){await run(async()=>{await api.apply({serviceType:applyType.value,gameIds:applyGames.value,introduction:introduction.value});await load(true);sheet.value=null;tab.value='me';notify('申请已提交，资料审核后安排考核');});}
async function availability(){await run(async()=>{await api.availability(!me.value?.available);await load(true);notify(me.value?.available?'已开启接单':'已切换为休息状态');});}
function navigate(next:string){tab.value=next==='hall'&&!canReceiveOrders.value?'home':next;statusFilter.value='all';if(next==='orders')orderScope.value='all';uni.pageScrollTo({scrollTop:0,duration:0});}
function openOrders(status='all'){navigate('orders');statusFilter.value=status;}
const tabs=[{id:'home',label:'发现',icon:'home'},{id:'hall',label:'接单',icon:'flag'},{id:'orders',label:'订单',icon:'list'},{id:'me',label:'我的',icon:'person'}];
const visibleTabs=computed(()=>tabs.filter(item=>item.id!=='hall'||canReceiveOrders.value));
let mounted=false;
function stopTimers(){clearInterval(interval);clearInterval(ticker);}
function startTimers(){stopTimers();interval=setInterval(()=>load(true),10000);ticker=setInterval(()=>now.value=Date.now(),1000);}
onMounted(async()=>{mounted=true;await load();});
onShow(()=>{platformLayout.value=getPlatformLayout();now.value=Date.now();if(mounted)void load(true);startTimers();});
onHide(stopTimers);
onUnmounted(()=>{stopTimers();clearTimeout(toastTimer);});
onResize(()=>{platformLayout.value=getPlatformLayout();});
onShareAppMessage(()=>({title:(settings.value?.name||'星曜电竞')+' · 好游戏，一起出发',path:'/pages/index/index'}));
</script>

<template>
  <view class="mobile-app" :class="{'is-weixin':isWeixinMiniProgram}" :style="appStyle">
    <view class="topbar" :style="topbarStyle"><view class="wordmark"><view class="star-mark">✳</view><view>{{settings?.name||'星曜电竞'}}<text>STELLAR CLUB</text></view></view><button v-if="!isWeixinMiniProgram" class="role-pill" :disabled="loading" @tap="sheet='accounts'"><view class="live-dot"/>{{identity.session?.name||'用户'}}<uni-icons type="bottom" color="#bfc1ca" :size="11"/></button><button v-if="!isWeixinMiniProgram" class="icon-btn" aria-label="帮助" @tap="sheet='help'"><uni-icons type="headphones" color="#d8dae3" :size="23"/></button></view>
    <view class="demo-strip"><view class="demo-dot"/> 演示模式 · 不产生真实扣款 <button :disabled="loading" @tap="sheet='accounts'">{{isWeixinMiniProgram?(identity.session?.name||'体验账号')+' · 切换':'体验账号'}}</button></view>
    <view v-if="error" class="error-box">{{error}}<button @tap="load()">重新加载</button></view>
    <view v-if="loading" class="loading"><view class="loading-ring"/> 正在加载…</view>
    <view v-else-if="tab==='home'||tab==='hall'" class="content">
      <view class="greeting">{{tab==='home'?'GOOD GAMES, GOOD COMPANY':'PLAY WITH PURPOSE'}}</view><view class="page-title">{{tab==='home'?'好游戏，一起出发':'发现新的协作'}}</view>
      <view v-if="tab==='home'" class="hero-banner"><view class="hero-copy"><view class="hero-kicker">YOUR NEXT GOOD GAME</view><view class="hero-title"><text class="hero-title-line">默契相遇</text><text class="hero-title-line">精彩加倍。</text></view><view class="hero-sub">选择游戏和服务，一键发起需求。</view><button class="primary compact" @tap="book()">快速邀请 <uni-icons type="arrow-right" :size="18" color="#11150c"/></button></view><view class="hero-orbit orbit-one"/><view class="hero-orbit orbit-two"/><view class="hero-spark">✳</view></view>
      <view class="service-switch"><button :class="{active:serviceType==='hourly'}" @tap="serviceType='hourly'"><text>{{tab==='home'?'邀请组队':'组队订单'}}</text><text>约定时长 · 轻松同行</text></button><button :class="{active:serviceType==='escort'}" @tap="serviceType='escort'"><text>{{tab==='home'?'邀请护航':'护航订单'}}</text><text>指定任务 · 目标达成</text></button></view>
      <scroll-view scroll-x class="game-scroll"><view class="game-filter"><button :class="{active:selectedGame==='all'}" @tap="selectedGame='all'">全部游戏</button><button v-for="g in games" :key="g.id" :class="{active:selectedGame===g.id}" @tap="selectedGame=g.id">{{g.name}}</button></view></scroll-view>
      <template v-if="tab==='home'"><view class="section-top"><view class="section-title">{{serviceType==='escort'?'护航服务商品':'组队服务商品'}}</view><text class="muted">{{displayProducts.length}} 件在售</text></view><view class="search-box"><uni-icons type="search" color="#858a9d" :size="20"/><input v-model="search" placeholder="搜索商品、游戏或服务成员"/></view>
        <view class="product-list"><view v-for="p in displayProducts" :key="p.id" class="product-card" @tap="openProduct(p)"><view class="product-game" :style="{background:gameColor(p.gameId)+'20',color:gameColor(p.gameId)}">{{games.find(g=>g.id===p.gameId)?.short}}</view><view class="product-info"><view class="product-title">{{p.title}}</view><view class="muted">{{p.serviceType==='escort'?p.task:'按约定小时提供服务'}}</view><view class="product-seller"><view class="seller-avatar" :style="{background:productSeller(p)?.color}">{{p.sellerName.slice(0,1)}}</view><text>{{p.sellerName}}</text><text class="seller-state" :class="serviceAvailability(productSeller(p)).state">{{serviceAvailability(productSeller(p)).label}}</text></view><view class="product-bottom"><view class="price">¥{{money(p.price)}}<text>/{{p.serviceType==='hourly'?'小时':'单'}}</text></view><text class="product-buy">{{p.userId===identity.session?.userId?'我的商品':serviceAvailability(productSeller(p)).action}} ›</text></view></view></view></view><view v-if="!displayProducts.length" class="empty">暂无符合条件的商品<text>也可以使用上方快速邀请发布服务需求</text></view>
      </template>
      <template v-else><view class="section-top hall-heading"><view><view class="section-title">{{serviceType==='escort'?'护航公共单':'组队公共单'}}</view><text class="section-hint">{{displayHall.length}} 个机会</text></view><view class="hall-filter-controls"><button class="hall-filter-toggle" role="switch" :aria-checked="hallFilterEnabled" :aria-label="hallFilterEnabled?'关闭条件过滤':'开启条件过滤'" @tap="toggleHallFilter"><view class="hall-filter-switch" :class="{on:hallFilterEnabled}"><view/></view><text>过滤</text></button><button class="hall-filter-button" :class="{active:hallFilteringActive}" aria-label="筛选公共单" @tap="openHallFilter"><uni-icons type="settings" :size="16" :color="hallFilteringActive?'#d9fd88':'#a4a8b7'"/><text>筛选{{hallFilterCount?' · '+hallFilterCount:''}}</text></button></view></view><view v-if="hallFilterCount" class="hall-filter-summary"><text>{{hallFilterEnabled?'':'未启用 · '}}{{hallFilterSummary}}</text><button @tap="clearHallFilter">清除筛选</button></view>
