?.available}">{{me?.available?'接单中 · 点击休息':'休息中 · 点击开启'}}</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="navigate('orders')"><uni-icons type="list" :size="21" color="#bdb5f5"/><text>我的订单</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='my-products'"><uni-icons type="shop" :size="21" color="#bdb5f5"/><text>我的商品</text><text class="menu-trailing">{{ownPublished}} 件在售</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='accounts'"><uni-icons type="loop" :size="21" color="#bdb5f5"/><text>切换体验账号</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button><button @tap="sheet='help'"><uni-icons type="headphones" :size="21" color="#bdb5f5"/><text>帮助与客服</text><uni-icons type="arrow-right" color="#7b7f90" :size="15"/></button></view><view class="profile-about"><view class="small-star">✳</view><text>STELLAR CLUB</text><view>好游戏，好队友。</view><text class="version">交互体验版 v2.1 · 数据仅保存在{{deviceDataLabel}}</text></view></view>
